-- GENERATED by tools/build.py. Do not edit.
-- Source of truth is queries/*.sql; edit there and rebuild.
-- Columns, in order: kind, id, ver, loc, extra, perms

-- from apps.sql
SELECT 'app' AS kind, bundle_identifier AS id, bundle_short_version AS ver, path AS loc,
       '' AS extra, '' AS perms
  FROM apps

UNION ALL

-- from browser.sql
SELECT 'ext' AS kind, identifier AS id, version AS ver, profile_path AS loc,
       browser_type AS extra,
       permissions || CASE WHEN manifest_json LIKE '%<all_urls>%' THEN ',<all_urls>' ELSE '' END
         AS perms
  FROM users CROSS JOIN chrome_extensions USING (uid)
UNION ALL
-- A single % matches ONE path component. 'Application Support/Google/Chrome/...' is TWO,
-- so the one-% form silently missed com.anthropic.claude_browser_extension.json.
-- Excluded by name, not by a 'com.apple.%' prefix. Stock macOS ships this iCloud Passwords
-- bridge in BOTH /Library/Google/Chrome and /Library/.../Mozilla, so every Mac in the fleet
-- reported two phantom native-messaging findings. Caught by the 00-baseline control, which
-- exists for precisely this. A prefix exclusion would be wider than the evidence supports and
-- would swallow any future first-party Apple Intelligence bridge, which we do want to see.
SELECT 'nmh', filename, '', path, '', '' FROM file
  WHERE path LIKE '/Users/%/Library/Application Support/%/NativeMessagingHosts/%.json'
    AND filename != 'com.apple.passwordmanager.json'
UNION ALL
SELECT 'nmh', filename, '', path, '', '' FROM file
  WHERE path LIKE '/Users/%/Library/Application Support/%/%/NativeMessagingHosts/%.json'
    AND filename != 'com.apple.passwordmanager.json'
UNION ALL
SELECT 'nmh', filename, '', path, '', '' FROM file
  WHERE path LIKE '/Library/%/%/NativeMessagingHosts/%.json'
    AND filename != 'com.apple.passwordmanager.json'

UNION ALL

-- from filesystem.sql
SELECT 'file' AS kind, path AS id, '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM file
  WHERE path LIKE '/Users/%/.local/bin/%'
UNION ALL
-- STATE DIRECTORIES, the most install-route-independent signal available: a cask, an npm
-- global, `curl install.sh | bash` and a source checkout all converge on the same dotdir
-- the first time the agent runs. Package-manager branches see only the route that was
-- used, and see nothing at all for a source build.
--
-- THE TRAILING SLASH IS LOAD-BEARING. osquery translates LIKE into its glob engine, where
-- a directory must be addressed with a trailing slash:
--     path LIKE '/Users/%/.claude'   -> 0 rows, no error
--     path LIKE '/Users/%/.claude/'  -> the directory
-- Same silent-zero shape as the JOIN and the one-% glob. Do not "tidy" the slash away.
--
-- Every top-level dotdir now, not four named ones. 47 on a loaded reference Mac, which is
-- affordable, and it means a new agent's state directory is evidence on the first scan
-- rather than after a fleet redeploy.
SELECT 'file', path, '', path, '', '' FROM file
  WHERE path LIKE '/Users/%/.%/'
UNION ALL
-- PYTHON-PACKAGED AGENTS. python_packages is deliberately absent from this query (15.6s,
-- no WHERE push-down), which would leave pipx, uv and pip --user installs invisible. That
-- is not a small corner: aider, litellm, crewai, langgraph, open-interpreter and most MCP
-- servers ship on PyPI first and some ONLY there.
--
-- The design justified dropping python_packages as contributing "zero Tier A matches",
-- but that was measured on a machine with none of them installed -- absence of evidence
-- read as evidence of absence.
--
-- So glob the INSTALL LOCATIONS instead of querying the slow table. Both managers give
-- each tool its own directory named for the package, which is precise, bounded and free.
-- These globs were already product-free and are unchanged.
SELECT 'file', path, '', path, '', '' FROM file
  WHERE path LIKE '/Users/%/.local/pipx/venvs/%/'
     OR path LIKE '/Users/%/.local/share/uv/tools/%/'
-- KNOWN GAP, deliberately not covered: packages executed via `npx`/`bunx` and never
-- installed. They land in a content-addressed cache, /Users/x/.npm/_npx/<hash>/
-- node_modules/<pkg>, where the invoked package is indistinguishable BY PATH from its
-- transitive dependencies. Measured on the reference Mac: globbing that cache generically
-- returns 1938 rows, and the scoped-only variant returns 123 which are almost entirely
-- @aws-sdk, @babel and @nodelib. The old branch avoided this only by naming two packages
-- outright, which is the practice this file exists to remove.
--
-- An agent run through npx still creates its state dotdir on first run and is caught by
-- the branch above. That reasoning is UNVERIFIED -- it has not been exercised against a
-- real npx-launched agent -- so it is recorded here as a gap rather than a mitigation.
-- Scenario 55-openclaw-npm is where it would be proven.

UNION ALL

-- from packages.sql
SELECT 'npm' AS kind, name AS id, version AS ver, path AS loc, '' AS extra, '' AS perms
  FROM npm_packages
  WHERE path NOT LIKE '%/node_modules/%/node_modules/%'
UNION ALL
-- homebrew_packages covers BOTH formulae and casks -- it has a `type` column returning
-- 'formula' or 'cask', and cask rows carry a /opt/homebrew/Caskroom/... path. An earlier
-- reading of this was wrong: a scenario installing an ollama formula AND an ollama-app
-- cask returned one row, and we concluded casks were unmodelled rather than checking.
-- `type` ships in `extra` so the collector can tell the install route apart.
SELECT 'brew', name, version, path, type, '' FROM homebrew_packages

UNION ALL

-- from runtime.sql
SELECT 'daemon' AS kind, label AS id, '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM launchd
  WHERE label NOT LIKE 'com.apple.%'
UNION ALL
-- Previously an IN list of four inference ports. A local model server on any other port
-- was invisible, and picking the port list on the device means a new runtime is missed
-- until every Mac is redeployed.
--
-- `port > 0` is structural, not selective: listening_ports rows with port 0 are unix
-- domain sockets and non-listening entries, 176 rows down to 34 on the reference Mac.
-- The bind address travels in `extra`, because 0.0.0.0 is a sharply higher-risk finding
-- than loopback and only the collector can weigh that.
SELECT 'port', CAST(lp.port AS TEXT), '', p.path, lp.address, ''
  FROM listening_ports lp JOIN processes p USING (pid)
  WHERE lp.port > 0;
